"""Tokenizer and parser for minisql queries.

Expressions are parsed into nested tuples whose first item is the node
type:

    ("lit", type_name, value)        literal (type name keeps 1 and TRUE apart)
    ("name", text)                   column name, before binding
    ("call", NAME, args, star)       function call, before binding
    ("neg", expr)
    ("arith", op, left, right)       op is one of + - * / ||
    ("cmp", op, left, right)         op is one of = != < <= > >=
    ("and", left, right)
    ("or", left, right)
    ("not", expr)
    ("isnull", expr, negated)
    ("in", expr, items, negated)
    ("between", expr, low, high, negated)
    ("like", expr, pattern, negated)

Tuples compare structurally, which is how GROUP BY expressions are matched.
"""

import re

from .errors import QueryError

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

_TOKEN_RE = re.compile(
    r"""
      (?P<space>\s+)
    | (?P<num>[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)
    | (?P<str>'(?:[^']|'')*')
    | (?P<qident>"(?:[^"]|"")*")
    | (?P<ident>[^\W\d]\w*)
    | (?P<op><=|>=|<>|!=|\|\||[=<>+\-*/(),;])
    """,
    re.VERBOSE,
)


class Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        self.kind = kind  # num, str, qident, ident, kw, op, eof
        self.value = value
        self.start = start
        self.end = end

    def describe(self):
        if self.kind == "eof":
            return "end of query"
        return repr(self.value) if self.kind != "kw" else self.value


def tokenize(sql):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if m is None:
            if sql[pos] in "'\"":
                raise QueryError("unterminated quoted text at position %d" % pos)
            raise QueryError("unexpected character %r at position %d" % (sql[pos], pos))
        kind = m.lastgroup
        text = m.group()
        if kind == "num":
            value = float(text) if "." in text else int(text)
        elif kind == "str":
            value = text[1:-1].replace("''", "'")
        elif kind == "qident":
            value = text[1:-1].replace('""', '"')
        elif kind == "ident":
            value = text
            if text.upper() in KEYWORDS:
                kind, value = "kw", text.upper()
        else:
            value = text
        if kind != "space":
            tokens.append(Token(kind, value, m.start(), m.end()))
        pos = m.end()
    tokens.append(Token("eof", None, len(sql), len(sql)))
    return tokens


class Column:
    """An item in the SELECT list."""

    def __init__(self, expr, alias, text):
        self.expr = expr
        self.alias = alias
        self.text = text


class Query:
    def __init__(self):
        self.distinct = False
        self.columns = None  # None means "*"
        self.table = None
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []  # (expr, descending)
        self.limit = None
        self.offset = 0


def parse(sql):
    try:
        return _Parser(sql).parse_query()
    except RecursionError:
        raise QueryError("query is too deeply nested") from None


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers

    @property
    def tok(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def at_kw(self, *words):
        return self.tok.kind == "kw" and self.tok.value in words

    def at_op(self, *ops):
        return self.tok.kind == "op" and self.tok.value in ops

    def accept_kw(self, word):
        if self.at_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.at_op(op):
            return self.advance()
        return None

    def expect_kw(self, word):
        if not self.at_kw(word):
            self.fail("expected %s" % word)
        return self.advance()

    def expect_op(self, op):
        if not self.at_op(op):
            self.fail("expected %r" % op)
        return self.advance()

    def fail(self, message):
        tok = self.tok
        raise QueryError(
            "syntax error at position %d: %s, found %s" % (tok.start, message, tok.describe())
        )

    def name(self):
        if self.tok.kind not in ("ident", "qident"):
            self.fail("expected a name")
        return self.advance().value

    def integer(self):
        if self.tok.kind != "num" or not isinstance(self.tok.value, int):
            self.fail("expected an integer")
        return self.advance().value

    # -- query

    def parse_query(self):
        q = Query()
        self.expect_kw("SELECT")
        q.distinct = bool(self.accept_kw("DISTINCT"))
        if not self.accept_op("*"):
            q.columns = [self.column()]
            while self.accept_op(","):
                q.columns.append(self.column())
        self.expect_kw("FROM")
        q.table = self.name()
        if self.accept_kw("WHERE"):
            q.where = self.expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            q.group_by = self.expr_list()
        if self.accept_kw("HAVING"):
            q.having = self.expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            q.order_by = [self.order_item()]
            while self.accept_op(","):
                q.order_by.append(self.order_item())
        if self.accept_kw("LIMIT"):
            q.limit = self.integer()
            if self.accept_kw("OFFSET"):
                q.offset = self.integer()
        self.accept_op(";")
        if self.tok.kind != "eof":
            self.fail("expected end of query")
        return q

    def column(self):
        first = self.pos
        expr = self.expr()
        text = self.sql[self.tokens[first].start : self.tokens[self.pos - 1].end]
        alias = None
        if self.accept_kw("AS"):
            alias = self.name()
        elif self.tok.kind in ("ident", "qident"):
            alias = self.name()
        return Column(expr, alias, text)

    def order_item(self):
        expr = self.expr()
        descending = False
        if self.accept_kw("DESC"):
            descending = True
        else:
            self.accept_kw("ASC")
        return expr, descending

    def expr_list(self):
        items = [self.expr()]
        while self.accept_op(","):
            items.append(self.expr())
        return items

    # -- expressions, lowest precedence first

    def expr(self):
        left = self.and_expr()
        while self.accept_kw("OR"):
            left = ("or", left, self.and_expr())
        return left

    def and_expr(self):
        left = self.not_expr()
        while self.accept_kw("AND"):
            left = ("and", left, self.not_expr())
        return left

    def not_expr(self):
        if self.accept_kw("NOT"):
            return ("not", self.not_expr())
        return self.comparison()

    def comparison(self):
        left = self.additive()
        while True:
            if self.at_op("=", "!=", "<>", "<", "<=", ">", ">="):
                op = self.advance().value
                left = ("cmp", "!=" if op == "<>" else op, left, self.additive())
            elif self.accept_kw("IS"):
                negated = bool(self.accept_kw("NOT"))
                self.expect_kw("NULL")
                left = ("isnull", left, negated)
            elif self.at_kw("NOT", "IN", "BETWEEN", "LIKE"):
                negated = bool(self.accept_kw("NOT"))
                if self.accept_kw("IN"):
                    self.expect_op("(")
                    items = tuple(self.expr_list())
                    self.expect_op(")")
                    left = ("in", left, items, negated)
                elif self.accept_kw("BETWEEN"):
                    low = self.additive()
                    self.expect_kw("AND")
                    left = ("between", left, low, self.additive(), negated)
                elif self.accept_kw("LIKE"):
                    left = ("like", left, self.additive(), negated)
                else:
                    self.fail("expected IN, BETWEEN, or LIKE")
            else:
                return left

    def additive(self):
        left = self.multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            left = ("arith", op, left, self.multiplicative())
        return left

    def multiplicative(self):
        left = self.unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = ("arith", op, left, self.unary())
        return left

    def unary(self):
        if self.accept_op("-"):
            return ("neg", self.unary())
        return self.primary()

    def primary(self):
        tok = self.tok
        if tok.kind in ("num", "str"):
            self.advance()
            return ("lit", type(tok.value).__name__, tok.value)
        if tok.kind == "kw" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[tok.value]
            return ("lit", type(value).__name__, value)
        if self.accept_op("("):
            inner = self.expr()
            self.expect_op(")")
            return inner
        if tok.kind == "ident" and self.tokens[self.pos + 1].kind == "op" and self.tokens[self.pos + 1].value == "(":
            self.pos += 2
            if self.accept_op("*"):
                self.expect_op(")")
                return ("call", tok.value.upper(), (), True)
            args = ()
            if not self.at_op(")"):
                args = tuple(self.expr_list())
            self.expect_op(")")
            return ("call", tok.value.upper(), args, False)
        if tok.kind in ("ident", "qident"):
            self.advance()
            return ("name", tok.value)
        self.fail("expected an expression")

