SCALARS = {  # name: (min args, max args or None for no limit)
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


class Result:
    """The result of a query: ``columns`` (names) and ``rows`` (tuples)."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)


def run(sql, directory="."):
    query = parse(sql)
    header, data = _load_table(directory, query.table)
    return _execute(query, header, data)


# -- tables


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory, name):
    if name in ("", ".", "..") or "/" in name or "\\" in name or "\0" in name:
        raise QueryError("invalid table name %r" % name)
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            records = list(csv.reader(f))
    except FileNotFoundError:
        raise QueryError("unknown table %r (no file %s)" % (name, path)) from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %r: %s" % (name, e)) from None
    if not records:
        raise QueryError("table %r has no header line" % name)
    header = records[0]
    rows = []
    for line_number, record in enumerate(records[1:], start=2):
        if not record:
            continue  # blank line
        if len(record) != len(header):
            raise QueryError(
                "table %r line %d has %d fields, expected %d"
                % (name, line_number, len(record), len(header))
            )
        rows.append(tuple(_convert(field) for field in record))
    return header, rows


# -- binding: resolve names, check functions and aggregate placement


class _Binder:
    def __init__(self, header):
        self.header = header
        self.index = {}
        self.ambiguous = set()
        for i, column in enumerate(header):
            key = column.lower()
            if key in self.index:
                self.ambiguous.add(key)
            else:
                self.index[key] = i
        self.used_aggregate = False

    def bind(self, node, clause, allow_aggregates=True, in_aggregate=False):
        kind = node[0]
        if kind == "lit":
            return node
        if kind == "name":
            key = node[1].lower()
            if key in self.ambiguous:
                raise QueryError("ambiguous column name %r" % node[1])
            if key not in self.index:
                raise QueryError("unknown column %r" % node[1])
            return ("col", self.index[key])
        if kind == "call":
            return self.bind_call(node, clause, allow_aggregates, in_aggregate)

        def sub(child):
            return self.bind(child, clause, allow_aggregates, in_aggregate)

        if kind in ("neg", "not"):
            return (kind, sub(node[1]))
        if kind in ("arith", "cmp"):
            return (kind, node[1], sub(node[2]), sub(node[3]))
        if kind in ("and", "or"):
            return (kind, sub(node[1]), sub(node[2]))
        if kind == "isnull":
            return (kind, sub(node[1]), node[2])
        if kind == "in":
            return (kind, sub(node[1]), tuple(sub(item) for item in node[2]), node[3])
        if kind == "between":
            return (kind, sub(node[1]), sub(node[2]), sub(node[3]), node[4])
        if kind == "like":
            return (kind, sub(node[1]), sub(node[2]), node[3])
        raise AssertionError(node)

    def bind_call(self, node, clause, allow_aggregates, in_aggregate):
        _, name, args, star = node
        if name in AGGREGATES:
            if in_aggregate:
                raise QueryError("aggregate %s can't be nested in another aggregate" % name)
            if not allow_aggregates:
                raise QueryError("aggregate %s can't be used in %s" % (name, clause))
            if star:
                if name != "COUNT":
                    raise QueryError("%s(*) is not allowed; only COUNT(*)" % name)
                self.used_aggregate = True
                return ("agg", name, None)
            if len(args) != 1:
                raise QueryError("%s takes 1 argument, got %d" % (name, len(args)))
            self.used_aggregate = True
            return ("agg", name, self.bind(args[0], clause, allow_aggregates, True))
        if name not in SCALARS:
            raise QueryError("unknown function %s" % name)
        if star:
            raise QueryError("%s(*) is not allowed; only COUNT(*)" % name)
        low, high = SCALARS[name]
        if len(args) < low or (high is not None and len(args) > high):
            if low == high:
                expected = "%d argument%s" % (low, "" if low == 1 else "s")
            elif high is None:
                expected = "at least %d argument%s" % (low, "" if low == 1 else "s")
            else:
                expected = "%d to %d arguments" % (low, high)
            raise QueryError("%s takes %s, got %d" % (name, expected, len(args)))
        bound = tuple(self.bind(a, clause, allow_aggregates, in_aggregate) for a in args)
        return ("func", name, bound)


def _subexpressions(node):
    kind = node[0]
    if kind in ("lit", "col"):
        return ()
    if kind in ("neg", "not", "isnull"):
        return (node[1],)
    if kind in ("arith", "cmp"):
        return (node[2], node[3])
    if kind in ("and", "or", "like"):
        return (node[1], node[2])
    if kind == "in":
        return (node[1],) + node[2]
    if kind == "between":
        return node[1:4]
    if kind == "func":
        return node[2]
    if kind == "agg":
        return () if node[2] is None else (node[2],)
    raise AssertionError(node)


def _check_grouped(node, group_exprs, header):
    """Check that every column outside an aggregate is in a GROUP BY expression."""
    if node in group_exprs or node[0] in ("lit", "agg"):
        return
    if node[0] == "col":
        raise QueryError(
            "column %r must appear in GROUP BY or be used in an aggregate" % header[node[1]]
        )
    for child in _subexpressions(node):
        _check_grouped(child, group_exprs, header)


# -- execution


def _execute(query, header, data):
    binder = _Binder(header)

    if query.columns is None:
        columns = [("col", i) for i in range(len(header))]
        names = list(header)
    else:
        columns = []
        names = []
        for column in query.columns:
            expr = binder.bind(column.expr, "SELECT")
            columns.append(expr)
            if column.alias is not None:
                names.append(column.alias)
            elif expr[0] == "col":
                names.append(header[expr[1]])
            else:
                names.append(column.text)

    where = None
    if query.where is not None:
        where = binder.bind(query.where, "WHERE", allow_aggregates=False)
    group_by = [binder.bind(e, "GROUP BY", allow_aggregates=False) for e in query.group_by]
    having = None
    if query.having is not None:
        having = binder.bind(query.having, "HAVING")

    # Each sort key is ("output", column index) or ("expr", bound expression).
    lowered_names = [n.lower() for n in names]
    order_by = []
    for expr, descending in query.order_by:
        if expr[0] == "name" and expr[1].lower() in lowered_names:
            key = ("output", lowered_names.index(expr[1].lower()))
        elif expr[0] == "lit" and expr[1] == "int":
            if not 1 <= expr[2] <= len(names):
                raise QueryError(
                    "ORDER BY position %d is out of range (1 to %d)" % (expr[2], len(names))
                )
            key = ("output", expr[2] - 1)
        else:
            key = ("expr", binder.bind(expr, "ORDER BY"))
        order_by.append((key, descending))

    grouped = bool(group_by) or binder.used_aggregate
    if grouped:
        group_set = set(group_by)
        for expr in columns:
            _check_grouped(expr, group_set, header)
        if having is not None:
            _check_grouped(having, group_set, header)
        for (kind, expr), _ in order_by:
            if kind == "expr":
                _check_grouped(expr, group_set, header)

    rows = [row for row in data if where is None or _evaluate(where, row, None) is True]

    if grouped:
        groups = {}
        for row in rows:
            key = tuple(_value_key(_evaluate(e, row, None)) for e in group_by)
            groups.setdefault(key, []).append(row)
        if not group_by:
            groups = {(): rows}
        # In a group, columns outside aggregates are GROUP BY expressions,
        # which are the same for every row, so the first row stands in.
        contexts = [(members[0] if members else None, members) for members in groups.values()]
    else:
        contexts = [(row, None) for row in rows]

    if having is not None:
        contexts = [c for c in contexts if _evaluate(having, c[0], c[1]) is True]

    results = []
    for row, members in contexts:
        values = tuple(_evaluate(e, row, members) for e in columns)
        keys = [
            values[expr] if kind == "output" else _evaluate(expr, row, members)
            for (kind, expr), _ in order_by
        ]
        results.append((values, keys))

    if query.distinct:
        seen = set()
        unique = []
        for values, keys in results:
            key = tuple(_value_key(v) for v in values)
            if key not in seen:
                seen.add(key)
                unique.append((values, keys))
        results = unique

    if order_by:
        directions = [descending for _, descending in order_by]

        def compare(a, b):
            for x, y, descending in zip(a[1], b[1], directions):
                c = _sort_compare(x, y)
                if c:
                    return -c if descending else c
            return 0

        results.sort(key=functools.cmp_to_key(compare))

    output = [values for values, _ in results]
    output = output[query.offset :]
    if query.limit is not None:
        output = output[: query.limit]
    return Result(names, output)


def _value_key(value):
    """A hashable key under which equal values (like 1 and 1.0) match."""
    if value is None:
        return (0,)
    if isinstance(value, bool):
        return (1, value)
    if isinstance(value, (int, float)):
        return (2, value)
    return (3, value)


# -- values


def _kind(value):
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _describe(value):
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    return repr(value)


def _compare(a, b):
    """Compare two non-NULL values, returning -1, 0, or 1."""
    if _kind(a) != _kind(b):
        raise QueryError("can't compare %s %s with %s %s" % (_kind(a), _describe(a), _kind(b), _describe(b)))
    return (a > b) - (a < b)


def _sort_compare(a, b):
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return _compare(a, b)


def _number(value, what):
    if _kind(value) != "number":
        raise QueryError("%s needs a number, got %s %s" % (what, _kind(value), _describe(value)))
    return value


def _string(value, what):
    if _kind(value) != "string":
        raise QueryError("%s needs a string, got %s %s" % (what, _kind(value), _describe(value)))
    return value


def _boolean(value, what):
    if value is not None and _kind(value) != "boolean":
        raise QueryError("%s needs a boolean, got %s %s" % (what, _kind(value), _describe(value)))
    return value


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _not(value):
    return None if value is None else not value


def _and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _like(value, pattern):
    regex = "".join(
        ".*" if ch == "%" else "." if ch == "_" else re.escape(ch) for ch in pattern
    )
    return re.fullmatch(regex, value, re.DOTALL) is not None


_DECIMAL_CONTEXT = decimal.Context(prec=1000, rounding=decimal.ROUND_HALF_UP)


def _round(x, places):
    """Round halves away from zero, using x's shortest decimal representation."""
    if places is None and isinstance(x, int):
        return x
    try:
        d = decimal.Decimal(repr(x))
        q = d.quantize(decimal.Decimal(1).scaleb(-(places or 0)), context=_DECIMAL_CONTEXT)
    except decimal.InvalidOperation:
        raise QueryError("can't round %r" % x) from None
    return int(q) if places is None else float(q)


_COMPARISONS = {
    "=": lambda c: c == 0,
    "!=": lambda c: c != 0,
    "<": lambda c: c < 0,
    "<=": lambda c: c <= 0,
    ">": lambda c: c > 0,
    ">=": lambda c: c >= 0,
}


def _evaluate(node, row, group):
    """Evaluate a bound expression on ``row``; aggregates run over ``group``."""
    kind = node[0]
    if kind == "col":
        return row[node[1]]
    if kind == "lit":
        return node[2]

    if kind == "and" or kind == "or":
        word = kind.upper()
        a = _boolean(_evaluate(node[1], row, group), word)
        b = _boolean(_evaluate(node[2], row, group), word)
        return _and(a, b) if kind == "and" else _or(a, b)
    if kind == "not":
        return _not(_boolean(_evaluate(node[1], row, group), "NOT"))
    if kind == "isnull":
        return (_evaluate(node[1], row, group) is None) != node[2]

    if kind == "neg":
        value = _evaluate(node[1], row, group)
        return None if value is None else -_number(value, "unary -")

    if kind == "arith":
        op = node[1]
        a = _evaluate(node[2], row, group)
        b = _evaluate(node[3], row, group)
        if a is None or b is None:
            return None
        if op == "||":
            return _text(a) + _text(b)
        _number(a, op)
        _number(b, op)
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if b == 0:
            return None
        return a / b

    if kind == "cmp":
        a = _evaluate(node[2], row, group)
        b = _evaluate(node[3], row, group)
        if a is None or b is None:
            return None
        return _COMPARISONS[node[1]](_compare(a, b))

    if kind == "in":
        value = _evaluate(node[1], row, group)
        result = False
        for item in node[2]:
            item = _evaluate(item, row, group)
            if value is None or item is None:
                result = None
            elif _compare(value, item) == 0:
                result = True
                break
        return _not(result) if node[3] else result

    if kind == "between":
        value = _evaluate(node[1], row, group)
        low = _evaluate(node[2], row, group)
        high = _evaluate(node[3], row, group)
        above = None if value is None or low is None else _compare(low, value) <= 0
        below = None if value is None or high is None else _compare(value, high) <= 0
        result = _and(above, below)
        return _not(result) if node[4] else result

    if kind == "like":
        value = _evaluate(node[1], row, group)
        pattern = _evaluate(node[2], row, group)
        if value is None or pattern is None:
            return None
        result = _like(_string(value, "LIKE"), _string(pattern, "LIKE"))
        return not result if node[3] else result

    if kind == "func":
        return _call(node[1], [_evaluate(arg, row, group) for arg in node[2]])

    if kind == "agg":
        return _aggregate(node[1], node[2], group)

    raise AssertionError(node)


def _call(name, args):
    if name == "COALESCE":
        for arg in args:
            if arg is not None:
                return arg
        return None
    if any(arg is None for arg in args):
        return None
    x = args[0]
    if name == "LOWER":
        return _string(x, name).lower()
    if name == "UPPER":
        return _string(x, name).upper()
    if name == "LENGTH":
        return len(_string(x, name))
    if name == "ABS":
        return abs(_number(x, name))
    if name == "ROUND":
        _number(x, name)
        places = None
        if len(args) == 2:
            places = args[1]
            if _kind(places) != "number" or not isinstance(places, int):
                raise QueryError("ROUND needs an integer number of places, got %s" % _describe(places))
        return _round(x, places)
    raise AssertionError(name)


def _aggregate(name, arg, group):
    if arg is None:  # COUNT(*)
        return len(group)
    values = [v for v in (_evaluate(arg, row, group) for row in group) if v is not None]
    if name == "COUNT":
        return len(values)
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for value in values:
            _number(value, name)
        total = sum(values)
        return total if name == "SUM" else total / len(values)
    best = values[0]
    for value in values[1:]:
        c = _compare(value, best)
        if (c < 0) if name == "MIN" else (c > 0):
            best = value
    return best

