        with open(path, newline="", encoding="utf-8-sig") as f:
            records = list(csv.reader(f))
    except FileNotFoundError:
        raise QueryError("unknown table %r (no file %s)" % (name, path)) from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %r: %s" % (name, e)) from None
    if not records:
        raise QueryError("table %r has no header line" % name)
    header = records[0]
    rows = []
    for line_number, record in enumerate(records[1:], start=2):
        if not record:
