        return (node[1],)
    if kind in ("arith", "cmp"):
        return (node[2], node[3])
    if kind in ("and", "or", "like"):
        return (node[1], node[2])
    if kind == "in":
        return (node[1],) + node[2]
    if kind == "between":
        return node[1:4]
    if kind == "func":
        return node[2]
    if kind == "agg":
